const DESKTOP_VIDEO = "https://www.dropbox.com/scl/fi/qtuzczykxuoa9q19lktyb/guestcam_16x9.mp4?rlkey=5w335kv6w5b90t8q4js3w7e3u&raw=1";

function SectionTitle({ eyebrow, title, text, light=false }: { eyebrow:string; title:string; text?:string; light?:boolean }) {
  return <div className="max-w-4xl"><p className={`text-xs font-black uppercase tracking-[.18em] ${light ? "text-[#F4B400]" : "text-[#8F6900]"}`}>{eyebrow}</p><h2 className={`mt-4 text-4xl font-black leading-[1.03] tracking-[-.05em] sm:text-6xl ${light ? "text-white" : ""}`}>{title}</h2>{text && <p className={`mt-5 text-lg leading-8 ${light ? "text-white/55" : "text-black/55"}`}>{text}</p>}</div>;
}

function LocalizedVideo({ t }: { t: Copy["video"] }) {
  return <section className="border-b border-black/10 bg-[#FFFDF8] py-20 sm:py-24"><div className="mx-auto max-w-[1500px] px-5 sm:px-8"><div className="mx-auto max-w-4xl text-center"><p className="text-xs font-black uppercase tracking-[.18em] text-[#8F6900]">{t.eyebrow}</p><h2 className="mt-4 text-4xl font-black tracking-[-.05em] sm:text-6xl">{t.title}</h2><p className="mx-auto mt-5 max-w-2xl text-lg leading-8 text-black/55">{t.lead}</p></div><div className="mx-auto mt-9 grid max-w-5xl gap-6 sm:grid-cols-3">{t.steps.map(([title,text],i)=><div key={title} className="border-t border-black/10 pt-4 text-left"><div className="flex gap-3"><span className="font-black text-[#8F6900]">{i+1}.</span><div><p className="font-black">{title}</p><p className="mt-1 text-sm leading-6 text-black/55">{text}</p></div></div></div>)}</div><div className="mt-12 overflow-hidden rounded-[32px] border border-black/10 bg-black shadow-2xl"><video controls playsInline preload="metadata" className="block aspect-video w-full bg-black object-contain"><source src={DESKTOP_VIDEO} type="video/mp4" /></video></div></div></section>;
}

